    'contribute.guides.writing.belief.desc':
      'COMPUTEX.md es un espacio curado, no una enciclopedia. No buscamos la exhaustividad — buscamos que cada artículo haga pensar a los lectores "¡Ah, ya veo!". Un buen artículo de COMPUTEX.md te dan ganas de contar a tus amigos: "Oye, ¿sabías que...?',
